contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry: attempt a refund; take a dummy uint parameter to make it parametric
    function run(uint256 dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // Record balances before calling refund
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // Call refund as its own top-level statement and capture whether it reverted
        bool refundReverted;
        c.refund(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            refundReverted = true;
        } else {
            refundReverted = false;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule:
        // - refund cannot increase c's balance (afterC <= beforeC)
        // - if refund succeeded, the decrease in c's balance equals the increase in this contract's balance
        assert(
            (afterC <= beforeC) &&
            (refundReverted ? (afterThis == beforeThis) : (beforeC - afterC == afterThis - beforeThis))
        );
    }

    // accept Ether sent from c.refund()
    receive() external payable {}
}

